test("terminal performs deterministic global repository audit before GestiaCore", () => {
    const terminal =
        fs.readFileSync(
            path.join(
                __dirname,
                "..",
                "gestia-terminal.html"
            ),
            "utf8"
        );

    const auditIndex =
        terminal.indexOf("TERMINAL_GLOBAL_REPO_AUDIT_41_44");

    const coreCallIndex =
        terminal.indexOf("await window.GestiaCore.procesarIntencion");

    assert.ok(auditIndex > 0);
    assert.ok(coreCallIndex > auditIndex);
    assert.match(terminal, /isExactGlobalRepoAuditCommand/);
    assert.match(terminal, /terminal_global_repo_audit_41_44/);
    assert.match(terminal, /\"repo\.audit\"/);
    assert.match(terminal, /ANÁLISIS GLOBAL DEL REPOSITORIO SIA7/);
    assert.match(terminal, /Archivos detectados/);
    assert.match(terminal, /Módulos detectados/);
    assert.match(terminal, /Funciones detectadas/);
    assert.match(terminal, /Flotilla/);
    assert.match(terminal, /Grafo incompleto/);
    assert.match(terminal, /Falsa lectura de impacto/);
    assert.match(terminal, /handled = true;[\s\S]{0,80}return;/);
});
